import React from 'react';
import Link from 'next/link';

export default function HeroSection({ title, subtitle, buttons }: { title: string; subtitle: string; buttons: { label: string; variant: 'primary' | 'secondary'; href: string }[] }) {
  return (
    <section className="py-24 md:py-40 bg-white">
      <div className="max-w-4xl mx-auto px-4 text-center">
        <h1 className="text-4xl md:text-6xl font-extrabold leading-tight mb-8 text-gray-900">
          {title}
        </h1>
        <p className="text-xl md:text-2xl text-gray-600 mb-12 max-w-2xl mx-auto leading-relaxed">
          {subtitle}
        </p>
        <div className="flex flex-wrap gap-4 justify-center">
          {buttons.map((btn, idx) => (
            <Link
              key={idx}
              href={btn.href}
              className={`px-8 py-4 rounded-full font-semibold transition-all duration-300 hover:scale-105 active:scale-95 shadow-lg inline-block ${btn.variant === 'secondary' ? 'bg-gray-100 text-gray-900 hover:bg-gray-200' : 'bg-blue-600 text-white hover:bg-blue-700'}`}
            >
              {btn.label}
            </Link>
          ))}
        </div>
      </div>
    </section>
  );
}
